        {
            outdir: copySamples,
            bundles: [
                {
                    bundleName: 'bad-sort',
                    manifest: 'bad-sort.manifest.json',
                },
            ],
        },
        function (error) {
            t.error(error);
            var result = require(
                path.join(copySamples, 'bad-sort.manifest.json')
            );

            t.equal(result.bundles.length, 4, 'removed one unused bundle');
            t.same(
                result.indexes,
